item.command:
/bin/bash -lc "python - <<'PY'
try:
    import bioblend, inspect
    from bioblend.galaxy.histories import HistoryClient
    print('bioblend', getattr(bioblend, '__version__', 'unknown'))
    for name in dir(HistoryClient):
        if 'histor' in name.lower() or 'copy' in name.lower():
            print(name)
except Exception as e:
    print(type(e).__name__, str(e))
PY"

/bin/bash -lc "python - <<'PY'
try:
    import bioblend, inspect
    from bioblend.galaxy.histories import HistoryClient
    print('bioblend', getattr(bioblend, '__version__', 'unknown'))
    for name in dir(HistoryClient):
        if 'histor' in name.lower() or 'copy' in name.lower():
            print(name)
except Exception as e:
    print(type(e).__name__, str(e))
PY"

